# New hypothesis: combine 2-box (rows 6-8) with 8-shape (rows 9-11)
# 8s overwrite 0s but not 2s, then fill remaining 0s with 5s

test_2box = [
    [2, 0, 2, 0, 2, 2],
    [2, 2, 0, 2, 2, 2],
    [2, 2, 2, 2, 2, 2]
]

test_8shape = [
    [0, 0, 8, 8, 0, 0],
    [0, 8, 0, 0, 8, 8],
    [0, 0, 0, 8, 0, 0]
]

# Combine 2-box + 8-shape: 8s replace 0s in 2-box at same column
combined = []
for r in range(3):
    combined_row = []
    row6 = test_2box[r]
    row8 = test_8shape[r]
    for c in range(6):
        if row8[c] == 8:
            combined_row.append(8)  # 8 at same column - overwrite
        elif row6[c] == 0:
            combined_row.append(0)  # 0 from 2-box
        else:
            combined_row.append(row6[c])  # keep 2
    combined.append(combined_row)

# Fill remaining 0s with 5s
final = []
for r in range(3):
    final_row = []
    for c in range(6):
        if combined[r][c] == 0:
            final_row.append(5)
        else:
            final_row.append(combined[r][c])
    final.append(final_row)

print("3x6 combined:")
for row in final:
    print(row)
